sql.if:
and exists ( select 1 from sys_user_role ur inner join sys_role r on r.role_id=ur.role_id and r.status='0' where ur.user_id=#{currentUserId}
and exists ( select 1 from sys_role_menu rm inner join sys_menu m on m.menu_id=rm.menu_id where rm.role_id=r.role_id and m.status='0' and m.perms is not null and m.perms!='' and find_in_set(m.perms,#{permissions}) > 0 )
and ( r.data_scope='1' or (r.data_scope='2' and b.dept_id in (select dept_id from sys_role_dept where role_id=r.role_id)) or (r.data_scope='3' and b.dept_id=#{currentDeptId}) or (r.data_scope='4' and b.dept_id in ( select sd.dept_id from sys_dept sd where sd.dept_id=#{currentDeptId} or find_in_set(#{currentDeptId},sd.ancestors) ))
or (r.data_scope='5' and (b.owner_id=#{currentUserId} or b.main_lawyer_id=#{currentUserId} or find_in_set(#{currentUserId},ifnull(b.assistant_lawyer_ids,''))))
or (r.data_scope='5' and b.owner_id=#{currentUserId})
) )
